pF(a,b,c){return"\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430\u2026 "+a+"% ("+b+" / "+c+")"},
pE(a){return"\u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c ("+a+")"},
gpz(){return"\u0421\u043a\u043e\u0440\u043e"},
glU(){return"\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0439"},
gpM(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
glT(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c"},
